pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // The freshly deployed contract has owner == address(0); the only caller
        // admitted by `onlyOwner` is therefore the zero address. Prank it and
        // let the FUZZED value `newOwner` drive the state change.
        vm.prank(address(0));
        try c.transferOwnership(newOwner) {
            // after a successful transfer, the rule must hold
            assertTrue(c.owner() == newOwner);
        } catch {
            assertTrue(false);
        }
    }
}

