pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        vm.assume(actor != address(0));

        // establish a non-trivial owner (initial owner is address(0), which is a valid caller)
        vm.prank(address(0));
        c.transferOwnership(newOwner);

        bool ok;
        vm.prank(actor);
        try c.owned() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a call to owned() succeeds exactly when the caller is the
        // current owner; if it fails, the revert must occur BEFORE any state effect
        // (here: ownership must still equal newOwner after any failed attempt).
        assertTrue(ok == (actor == c.owner()) && c.owner() == newOwner);
    }
}

