contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address a, address b) public {
        vm.assume(a != address(0));
        vm.assume(b != address(0));
        vm.assume(a != b);
        vm.assume(a != address(this));
        vm.assume(b != address(this));
        // owner (the deployer, address(this)) transfers ownership to a
        c.transferOwnership(a);
        // a calls owned(); it must complete but leave owner untouched
        vm.prank(a);
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        assertTrue(ok && c.owner() == a);
    }
}
